const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');

class StorageError extends Error {}

function keyToPath(storageDir, key) {
  // Keys are opaque identifiers generated by this adapter; reject any traversal attempt.
  if (typeof key !== 'string' || key.length === 0 || path.basename(key) !== key || key !== encodeURIComponent(key)) {
    throw new StorageError('Invalid storage key.');
  }
  return path.resolve(storageDir, key);
}

/**
 * Storage adapter (C-STO): put/get/remove over a local directory that must
 * back a Docker volume in deployment. Files are never exposed through any
 * static middleware; downloads route through authorised API endpoints.
 */
function createStorage({ storageDir } = {}) {
  const dir = path.resolve(storageDir || 'data/uploads');

  function ensureDir() {
    fs.mkdirSync(dir, { recursive: true });
  }

  async function put(key, buffer) {
    ensureDir();
    const target = keyToPath(dir, key);
    await fsp.writeFile(target, buffer);
    return { key, path: target };
  }

  async function get(key) {
    ensureDir();
    const target = keyToPath(dir, key);
    return fsp.readFile(target);
  }

  async function remove(key) {
    const target = keyToPath(dir, key);
    await fsp.rm(target, { force: true });
  }

  return { put, get, remove };
}

module.exports = { createStorage, keyToPath, StorageError };
